// Real Chromium rendering and PNG export; no DOM/canvas mocks.
const fs = require('fs');
const path = require('path');
const { pathToFileURL } = require('url');
const { spawnSync } = require('child_process');
const assert = require('assert');
const root = path.resolve(__dirname, '..');
const output = path.join(root, 'out', 'rich-qa');
fs.mkdirSync(output, { recursive: true });
const browser = process.env.CHROME_PATH || ['C:/Program Files/Google/Chrome/Application/chrome.exe', '/usr/bin/chromium', '/usr/bin/google-chrome'].find(p => fs.existsSync(p));
assert.ok(browser, 'Set CHROME_PATH to a Chromium browser executable');
let html = fs.readFileSync(path.join(root, 'src/mindmapEditorProvider.ts'), 'utf8').match(/return `(<!DOCTYPE[\s\S]*?)`;/)[1];
// Keep the same CSP restrictions used by the actual webview, with file: as cspSource.
html = html.replaceAll('${csp}', 'file:');
for (const [key, file] of Object.entries({ cssUri: 'style.css', coreUri: 'core.js', appUri: 'mindsprout.js', bootstrapUri: 'bootstrap.js', richUri: 'rich.js', mermaidUri: 'vendor/mermaid.min.js' })) {
  html = html.replaceAll('${' + key + '}', pathToFileURL(path.join(root, 'media', file)).href);
}
const markdown = '# 富内容导入\n## 表格\n| 名称 | 状态 |\n| --- | --- |\n| 接口 | 已完成 |\n| 页面 | 进行中 |\n## 代码\n```javascript\nfunction greet(name) {\n  return `你好 ${name}`;\n}\n```\n## 流程图\n```mermaid\nflowchart LR\n  A[开始] --> B{验证}\n  B -->|通过| C[完成]\n```\n## 错误图表\n```mermaid\nnot a diagram\n```';
const boot = `
window.acquireVsCodeApi = () => ({ postMessage: msg => {
  if (msg.type === 'resolve-image') setTimeout(()=>window.dispatchEvent(new MessageEvent('message',{data:{type:'image-resolved',requestId:msg.requestId,...(msg.src==='resources/icon.png'?{dataUri:"data:image/png;base64,"}:{error:'图片不存在'})}})),0);
  if (window.imageExport && msg.type==='export') {
    if(msg.format==='svg') document.body.dataset.imagesvg=String(msg.content.includes('data:image/png;base64,') && msg.content.includes('<img'));
    if(msg.format==='html') document.body.dataset.imagehtml=String(msg.content.includes('data:image/png;base64,') && msg.content.includes('<img'));
    if(msg.format==='png') document.body.dataset.imagepng=String(msg.pngBase64.length>1000);
    return;
  }
  if (msg.type === 'ready') setTimeout(() => window.dispatchEvent(new MessageEvent('message', { data: { type: 'init', data: MindMapCore.markdownImport(${JSON.stringify(markdown)}) } })), 0);
  if (msg.type === 'export' && msg.format === 'png') {
    document.body.dataset.png = String(msg.pngBase64.length);
    if (window.longExport) {
      const image = new Image();
      image.onload = () => document.body.dataset.longpng = JSON.stringify({width:image.width,height:image.height});
      image.src = 'data:image/png;base64,' + msg.pngBase64;
    }
  }
  if (msg.type === 'export' && msg.format === 'svg') document.body.dataset.svg = btoa(unescape(encodeURIComponent(msg.content)));
  if (msg.type === 'export' && msg.format === 'html') document.body.dataset.html = String(msg.content.includes('<table') && msg.content.includes('<svg'));
}});
window.addEventListener('error', e => document.body.dataset.error = e.message);
setTimeout(() => {
  const rail=document.getElementById('toolbar').getBoundingClientRect();
  const layoutButton=document.querySelector('[data-action="layout-toggle"]');layoutButton.click();
  const menu=document.getElementById('layout-menu').getBoundingClientRect();
  const railCheck={vertical:rail.height>rail.width,canvas:document.getElementById('canvas-wrap').getBoundingClientRect().top===0,icons:document.querySelectorAll('#toolbar .tb-tool svg').length,menu:menu.left>=rail.right && menu.bottom<=innerHeight};
  layoutButton.dispatchEvent(new MouseEvent('pointerover',{bubbles:true}));
  railCheck.tip=!document.getElementById('toolbar-tooltip').hidden;
  layoutButton.click();document.body.dataset.rail=JSON.stringify(railCheck);
  document.body.dataset.defaultzoom = document.getElementById('zoom-label').textContent;
  const nodes = [...document.querySelectorAll('.mm-node')].map(n => ({x:n.offsetLeft,y:n.offsetTop,w:n.offsetWidth,h:n.offsetHeight}));
  const overlap = nodes.some((a,i) => nodes.slice(i+1).some(b => a.x < b.x+b.w && b.x < a.x+a.w && a.y < b.y+b.h && b.y < a.y+a.h));
  document.body.dataset.qa = JSON.stringify({ tables: document.querySelectorAll('.mm-rich table').length, code: document.querySelectorAll('.mm-rich-code pre').length, diagrams: document.querySelectorAll('.mm-rich-mermaid svg').length, fallback: [...document.querySelectorAll('.mm-rich-mermaid .mm-code-label')].some(n=>n.textContent.includes('语法错误')), overlap });
  const background=document.getElementById('canvas-color');background.value='#f1e2d3';background.dispatchEvent(new Event('input',{bubbles:true}));
  document.body.dataset.background=getComputedStyle(document.getElementById('canvas-wrap')).backgroundColor;
  const target = document.querySelectorAll('.mm-node')[1];
  target.dispatchEvent(new MouseEvent('pointerdown', { bubbles: true, button: 0 }));
  for (const [id,value] of [['line-color','#d93658'],['text-color','#7b239f'],['font-weight','700']]) {
    const input = document.getElementById(id); input.value=value; input.dispatchEvent(new Event('input',{bubbles:true}));
  }
  const styled = document.querySelector('.mm-node[data-id="'+target.dataset.id+'"]');
  document.body.dataset.styles = JSON.stringify({ color:getComputedStyle(styled).color, weight:getComputedStyle(styled).fontWeight, lines:[...document.querySelectorAll('#edges path')].some(p=>p.getAttribute('stroke')==='#d93658'), transform:getComputedStyle(document.getElementById('world')).transform, hint:document.getElementById('style-hint').textContent });
  document.querySelector('[data-action="zoom-in"]').click();
  const zoomWorld = document.getElementById('world');
  const zoomNode = styled.getBoundingClientRect();
  const zoomScale = parseFloat(zoomWorld.style.zoom);
  document.body.dataset.zoomposition = String(Math.abs(zoomNode.left - (document.getElementById('canvas-wrap').getBoundingClientRect().left + (parseFloat(zoomWorld.style.left) + parseFloat(styled.style.left)) * zoomScale)) < 1);
  document.querySelector('[data-action="zoom-reset"]').click();
  const nodeRect=styled.getBoundingClientRect();
  document.body.dataset.position = String(Math.abs(nodeRect.left - (document.getElementById('canvas-wrap').getBoundingClientRect().left + parseFloat(document.getElementById('world').style.left) + parseFloat(styled.style.left))) < 1);
  document.querySelector('[data-action="export-png"]').click();
  document.querySelector('[data-action="export-html"]').click();
  document.querySelector('[data-action="style-toggle"]').click();
  const swatch = document.querySelector('[data-color-target="line-color"][data-color="#00b96b"]');
  swatch.click();
  document.querySelector('[data-color-target="text-color"][data-color="#1d4ed8"]').click();
  document.body.dataset.palette = String(document.getElementById('line-color').value === '#00b96b' && document.getElementById('text-color').value === '#1d4ed8');
  document.getElementById('canvas-wrap').dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,button:0}));
  document.body.dataset.menudismissed = String(getComputedStyle(document.getElementById('style-menu')).display === 'none');
  document.querySelector('[data-action="export-svg"]').click();
  document.querySelector('[data-action="layout-right"]').click();
  document.querySelector('[data-action="layout-org"]').click();
  const mini = document.getElementById('minimap-canvas');
  const nodeCount = document.querySelectorAll('.mm-node').length;
  const miniCount = mini.querySelectorAll('.minimap-nodes rect').length;
  const busCount = document.querySelectorAll('#edges [data-edge-role="bus"]').length;
  document.body.dataset.layoutzoom = document.getElementById('zoom-label').textContent;
  const rounded = [...document.querySelectorAll('#edges [data-edge-role="branch"]')].some(p=>p.getAttribute('d').includes(' Q'));
  const navRect = mini.getBoundingClientRect();
  const navWorld = document.getElementById('world');
  const viewWidth = parseFloat(mini.querySelector('.minimap-viewport').getAttribute('width'));
  const initialLeft = navWorld.style.left;
  mini.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,button:0,clientX:navRect.left+navRect.width*.3,clientY:navRect.top+navRect.height*.4}));
  window.dispatchEvent(new PointerEvent('pointermove',{clientX:navRect.left+navRect.width*.6,clientY:navRect.top+navRect.height*.6}));
  window.dispatchEvent(new PointerEvent('pointerup'));
  const moved = initialLeft !== navWorld.style.left;
  document.querySelector('[data-action="zoom-in"]').click();
  const zoomed = parseFloat(mini.querySelector('.minimap-viewport').getAttribute('width')) < viewWidth;
  document.getElementById('minimap-toggle').click();
  const hidden = getComputedStyle(mini).display === 'none';
  document.getElementById('minimap-toggle').click();
  document.getElementById('minimap-fit').click();
  document.body.dataset.navigator = JSON.stringify({nodeCount,miniCount,busCount,rounded,moved,zoomed,hidden,shown:getComputedStyle(mini).display!=='none'});
  document.querySelector('[data-action="export-svg"]').click();
  const bulk = document.getElementById('btn-toggle-all-nodes');
  const bulkInitial = bulk.textContent;
  bulk.click();
  bulk.click();
  const bulkExpanded = bulk.textContent;
  bulk.click();
  const bulkCollapsed = bulk.textContent;
  const collapsedCount = document.querySelectorAll('.mm-node').length;
  const miniCollapsed = document.querySelectorAll('.minimap-nodes rect').length;
  bulk.click();
  document.body.dataset.bulk = JSON.stringify({initial:bulkInitial,expanded:bulkExpanded,collapsed:bulkCollapsed,collapsedCount,miniCollapsed,restored:document.querySelectorAll('.mm-node').length===nodeCount,zoom:document.getElementById('zoom-label').textContent});


}, 10000);
setTimeout(() => {
  const data = MindMapCore.defaultData();
  data.root.text = '长代码导出';
  const code = MindMapCore.createNode(Array.from({length:280}, (_,i) => 'const item' + i + ' = "高清导出";').join('\\n'));
  code.content = {type:'code',language:'javascript'};
  data.root.children.push(code);
  window.dispatchEvent(new MessageEvent('message',{data:{type:'init',data}}));
  window.longExport = true;
  document.querySelector('[data-action="export-png"]').click();
}, 11000);
setTimeout(() => {
  const C=MindMapCore,data=C.defaultData();data.root.text='紧凑排列';
  const tableSource='| 名称 | 状态 |\\n| --- | --- |\\n'+Array.from({length:6},(_,i)=>'| 表格内容'+i+' | 已完成 |').join('\\n');
  const upper=C.createNode(tableSource),lower=C.createNode(tableSource);
  upper.content={type:'table'};lower.content={type:'table'};
  lower.text += '\\n' + Array.from({length:5},(_,i)=>'| 额外行'+i+' | 不同高度 |').join('\\n');
  const wide=C.createNode('const '+ 'identifier'.repeat(15)+' = 1;');wide.content={type:'code',language:'javascript'};
  const tall=C.createNode(Array.from({length:80},(_,i)=>'const value'+i+' = 1;').join('\\n'));tall.content={type:'code',language:'javascript'};
  wide.children.push(tall);
  data.root.children=[C.createNode('上表',[upper]),C.createNode('中间分支',[wide]),C.createNode('下表',[lower])];
  window.dispatchEvent(new MessageEvent('message',{data:{type:'init',data}}));
  document.querySelector('[data-action="layout-right"]').click();
  const a=document.querySelector('.mm-node[data-id="'+upper.id+'"]').getBoundingClientRect();
  const b=document.querySelector('.mm-node[data-id="'+lower.id+'"]').getBoundingClientRect();
  const nodes=[...document.querySelectorAll('.mm-node')].map(node=>node.getBoundingClientRect());
  const overlap=nodes.some((a,i)=>nodes.slice(i+1).some(b=>a.left<b.right-.1&&b.left<a.right-.1&&a.top<b.bottom-.1&&b.top<a.bottom-.1));
  document.body.dataset.contour=JSON.stringify({gap:b.top-a.bottom,overlap,zoom:document.getElementById('zoom-label').textContent});
  const deltas=[];
  for(const mode of ['right','left','org','up']) {
    document.querySelector('[data-action="layout-'+mode+'"]').click();
    const p=document.querySelector('.mm-node[data-id="'+data.root.id+'"]').getBoundingClientRect();
    const m=document.querySelector('.mm-node[data-id="'+data.root.children[1].id+'"]').getBoundingClientRect();
    deltas.push(mode==='org'||mode==='up'?Math.abs(p.left+p.width/2-m.left-m.width/2):Math.abs(p.top+p.height/2-m.top-m.height/2));
  }
  document.body.dataset.middlealignment=JSON.stringify(deltas);
  document.querySelector('[data-action="layout-right"]').click();

}, 12000);
setTimeout(()=>{
  window.dispatchEvent(new MessageEvent('message',{data:{type:'init',markdown:'# 图片预览\\n<p align="center">\\n<img src="resources/icon.png" alt="思络图标" width="128" height="128" onerror="alert(1)" />\\n</p>\\n\\n![同一图标](resources/icon.png)\\n\\n![丢失图片](missing.png)',readOnly:true,fileName:'README.md'}}));
},13000);
setTimeout(()=>{
  const images=[...document.querySelectorAll('.mm-rich-image img')];
  document.body.dataset.imagerender=JSON.stringify({count:images.length,loaded:images.every(img=>img.complete&&img.naturalWidth>0),width:images[0]?.getBoundingClientRect().width,unsafe:images.some(img=>img.hasAttribute('onerror')),fallback:document.querySelector('#nodes').textContent.includes('图片不存在')});
  window.imageExport=true;
  for(const format of ['svg','html','png'])document.querySelector('[data-action="export-'+format+'"]').click();
},14000);
setTimeout(()=>{
  const data=MindMapCore.defaultData();data.root.text='中心主题输入';
  window.dispatchEvent(new MessageEvent('message',{data:{type:'init',data}}));
  const results=[];
  for(const key of ['lightMap','fresh','night']) {
    document.querySelector('[data-theme="'+key+'"]').click();
    document.querySelector('.mm-node').dispatchEvent(new MouseEvent('dblclick',{bubbles:true}));
    const input=document.querySelector('.mm-editor');const style=getComputedStyle(input);
    results.push({color:style.color,background:style.backgroundColor,caret:style.caretColor});
    input.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));
  }
  document.body.dataset.editorcontrast=JSON.stringify(results);
},14500);

`;
fs.writeFileSync(path.join(output, 'boot.js'), boot);
html = html.replace('<script src=', '<script src="' + pathToFileURL(path.join(output, 'boot.js')).href + '"></script><script src=');
const preview = path.join(output, 'preview.html');
fs.writeFileSync(preview, html);
const result = spawnSync(browser, ['--headless', '--disable-gpu', '--no-sandbox', '--disable-extensions', '--allow-file-access-from-files', '--user-data-dir=' + path.join(output, 'chrome-profile'), '--virtual-time-budget=15000', '--dump-dom', '--screenshot=' + path.join(output, 'preview.png'), '--window-size=1500,1000', pathToFileURL(preview).href], { encoding: 'utf8', timeout: 60000, maxBuffer: 8 * 1024 * 1024 });
assert.strictEqual(result.status, 0, result.stderr);
fs.writeFileSync(path.join(output, 'dom.html'), result.stdout);
const read = key => result.stdout.match(new RegExp('data-' + key + '="([^"]*)"'))?.[1].replaceAll('&quot;', '"').replaceAll('&amp;', '&');
assert.ok(!read('error'), read('error'));
for(const editor of JSON.parse(read('editorcontrast'))) {assert.notStrictEqual(editor.color,editor.background);assert.strictEqual(editor.color,editor.caret);}
assert.deepStrictEqual(JSON.parse(read('imagerender')), {count:2,loaded:true,width:128,unsafe:false,fallback:true});
for(const key of ['imagesvg','imagehtml','imagepng'])assert.strictEqual(read(key),'true',key);
assert.deepStrictEqual(JSON.parse(read('rail')), {vertical:true,canvas:true,icons:13,menu:true,tip:true});
assert.deepStrictEqual(JSON.parse(read('qa')), { tables: 1, code: 1, diagrams: 1, fallback: true, overlap: false });
const contour=JSON.parse(read('contour'));
assert.ok(contour.gap>0 && contour.gap<200, 'Table gap: '+contour.gap);
assert.strictEqual(contour.overlap,false);
assert.strictEqual(contour.zoom,'100%');
assert.ok(JSON.parse(read('middlealignment')).every(delta=>delta<1), 'Parent aligns with middle child in each layout');
assert.ok(Number(read('png')) > 1000, 'PNG export succeeded with a real canvas');
assert.strictEqual(read('html'), 'true');
assert.strictEqual(read('background'),'rgb(241, 226, 211)');
assert.strictEqual(read('defaultzoom'), '100%');
assert.strictEqual(read('layoutzoom'), '100%');
const styles = JSON.parse(read('styles'));
assert.strictEqual(styles.color, 'rgb(123, 35, 159)');
assert.strictEqual(styles.weight, '700');
assert.strictEqual(styles.lines, true);
assert.strictEqual(styles.transform, 'none');
assert.strictEqual(read('position'), 'true');
assert.strictEqual(read('zoomposition'), 'true');
assert.strictEqual(read('palette'), 'true');
assert.strictEqual(read('menudismissed'), 'true');
assert.ok(JSON.parse(read('longpng')).height > 10000, 'Long diagram PNG retains high resolution above 4096px');
const vector = Buffer.from(read('svg'), 'base64').toString('utf8');
assert.ok(vector.includes('<foreignObject') && vector.includes('<table'));
assert.ok(vector.includes('#f1e2d3')); 
assert.ok(!vector.includes('id="minimap"'));
const bulk = JSON.parse(read('bulk'));
assert.strictEqual(bulk.initial, '节点一键收起');
assert.strictEqual(bulk.expanded, '节点一键收起');
assert.strictEqual(bulk.collapsed, '节点一键展开');
assert.strictEqual(bulk.collapsedCount, 1);
assert.strictEqual(bulk.miniCollapsed, 1);
assert.strictEqual(bulk.restored, true);
const navigator = JSON.parse(read('navigator'));
assert.strictEqual(navigator.miniCount, navigator.nodeCount);
assert.ok(navigator.busCount > 0);
for (const flag of ['rounded','moved','zoomed','hidden','shown']) assert.strictEqual(navigator[flag], true, flag);
fs.writeFileSync(path.join(output, 'export.svg'), vector);
console.log('Rich browser rendering, error fallback, layout, PNG and HTML export passed.');
